import express from 'express';import dotenv from 'dotenv';import fs from 'node:fs';dotenv.config();const app=express();app.use(express.json());const PORT=Number(process.env.MCP_CPU_HUB_PORT||7191);function sink(o){const p=process.env.CPU_QUEUE||'/var/lib/exosys-hub/cpu-queue.ndjson';fs.mkdirSync(p.split('/').slice(0,-1).join('/'),{recursive:true});fs.appendFileSync(p,JSON.stringify(o)+'\n')}app.get('/health',(_q,r)=>r.json({ok:true,service:'mcp-cpu-hub'}));app.post('/task',(q,r)=>{const o={time:Date.now()/1000,kind:'cpu-task',status:'queued',...q.body};sink(o);r.json({ok:true,task:o})});app.listen(PORT,'0.0.0.0',()=>console.log('mcp cpu hub',PORT));